-- +goose Up
-- Step 3b, zone needs (D186, D324-): what a room needs (lights, blinds,
-- sockets, ...), saved with a plan's content, and room templates (catalog
-- configuration) that fill a zone's needs quickly.

-- Function types can be retired: an inactive one is kept on existing needs
-- (warning need_function_type_inactive) but not chosen for new ones.
ALTER TABLE function_types ADD COLUMN is_active boolean NOT NULL DEFAULT true;

-- Needs of a plan. Tenant-owned like plan_zones (composite key to the plan,
-- RLS). Ids are generated by the client, unique per plan.
CREATE TABLE plan_needs (
    plan_id          uuid NOT NULL,
    id               uuid NOT NULL,
    tenant_id        uuid NOT NULL,
    -- RESTRICT: a function type needs use cannot be deleted
    -- (function_type.in_use).
    function_type_id uuid NOT NULL REFERENCES function_types (id) ON DELETE RESTRICT,
    quantity         integer NOT NULL CHECK (quantity BETWEEN 1 AND 100),
    -- Power per unit in W.
    power_w          double precision CHECK (power_w IS NULL OR (power_w >= 0 AND power_w <= 100000)),
    -- RESTRICT: load_type.in_use.
    load_type_id     uuid REFERENCES load_types (id) ON DELETE RESTRICT,
    label            text NOT NULL DEFAULT '' CHECK (char_length(label) <= 100),
    note             text NOT NULL DEFAULT '' CHECK (char_length(note) <= 500),
    -- Set: a load symbol on the plan, its zone computed by the backend.
    x                double precision,
    y                double precision,
    -- The zone (for a symbol computed on every save; NULL = outside every
    -- zone). No foreign key: zones and needs are replaced together.
    zone_id          uuid,
    position         integer NOT NULL,
    PRIMARY KEY (plan_id, id),
    CHECK ((x IS NULL) = (y IS NULL)),
    CHECK (x IS NOT NULL OR zone_id IS NOT NULL),
    FOREIGN KEY (plan_id, tenant_id) REFERENCES plans (id, tenant_id) ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE INDEX plan_needs_function_type_idx ON plan_needs (function_type_id);
CREATE INDEX plan_needs_load_type_idx ON plan_needs (load_type_id);

ALTER TABLE plan_needs ENABLE ROW LEVEL SECURITY;
ALTER TABLE plan_needs FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON plan_needs
    USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid
           OR current_setting('app.access_all', true) = 'on')
    WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid
           OR current_setting('app.access_all', true) = 'on');
GRANT SELECT, INSERT, UPDATE, DELETE ON plan_needs TO snapflow_app;

-- Room templates: global catalog configuration (no tenant data, no RLS).
CREATE TABLE room_templates (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    key             text NOT NULL UNIQUE CHECK (key ~ '^[a-z][a-z0-9_]*$' AND char_length(key) <= 64),
    name            jsonb NOT NULL,
    -- Optional translatable equipment level ("Basic", "Comfort").
    equipment_level jsonb,
    sort_order      integer NOT NULL,
    is_active       boolean NOT NULL DEFAULT true,
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE room_template_lines (
    template_id      uuid NOT NULL REFERENCES room_templates (id) ON DELETE CASCADE,
    position         integer NOT NULL,
    -- RESTRICT: function_type.in_use / load_type.in_use.
    function_type_id uuid NOT NULL REFERENCES function_types (id) ON DELETE RESTRICT,
    quantity         integer NOT NULL CHECK (quantity BETWEEN 1 AND 100),
    power_w          double precision CHECK (power_w IS NULL OR (power_w >= 0 AND power_w <= 100000)),
    load_type_id     uuid REFERENCES load_types (id) ON DELETE RESTRICT,
    label            text NOT NULL DEFAULT '' CHECK (char_length(label) <= 100),
    PRIMARY KEY (template_id, position)
);
CREATE INDEX room_template_lines_function_type_idx ON room_template_lines (function_type_id);
CREATE INDEX room_template_lines_load_type_idx ON room_template_lines (load_type_id);

-- +goose Down
DROP TABLE room_template_lines;
DROP TABLE room_templates;
DROP TABLE plan_needs;
ALTER TABLE function_types DROP COLUMN is_active;
